<template><AppShell title="道具市场" tab="market"><view class="market-top pad"><view class="search"><AppIcon class="app-icon" name="search" :size="19" /><input v-model="keyword" @blur="keyword=$event.detail.value" placeholder="搜索地铁逃生装备、密钥与道具" confirm-type="search" @confirm="keyword=$event.detail.value;search()" /><button class="ui-button text-button" @click="search">搜索</button></view><button class="ui-button player-search-entry" @click="go('players/search',{userNo:/^(?:1[0-9]{4}|KK[0-9]{6,19})$/i.test(keyword.trim())?keyword.trim():undefined})">按用户编号查找玩家 ›</button><view class="categories"><button class="ui-button" v-for="g in games" :key="g" :class="{chosen:game===g}" @click="game=g;load()"><view v-if="g==='全部'" class="all-icon"><AppIcon class="app-icon" name="grid" :size="27" /></view><GameArt variant="shortcut" v-else game="和平精英" /><text>{{g}}</text></button></view></view><view class="tabs"><button class="ui-button" v-for="s in sorts" :key="s.value" :class="{selected:sort===s.value}" @click="sort=s.value;load()">{{s.label}}</button></view><view class="pad"><StateView :loading="loading" :error="error" :count="items.length" title="没有找到相关道具" description="试试其他道具分类或关键词" @retry="load()" /><view class="service-grid"><ServiceCard v-for="item in items" :key="item.id" :item="item" /></view><button v-if="items.length<total" class="ui-button load-more" :disabled="loading" @click="more">{{loading?'加载中…':'查看更多道具'}}</button></view></AppShell></template>
<script setup>
import {ref} from 'vue';import {onLoad,onShow,onReachBottom} from '@dcloudio/uni-app';import AppShell from '../../components/AppShell.vue';import AppIcon from '../../components/AppIcon.vue';import GameArt from '../../components/GameArt.vue';import ServiceCard from '../../components/ServiceCard.vue';import StateView from '../../components/StateView.vue';import {useList} from '../../lib/useList';import {go} from '../../lib/api';import {ITEM_CATEGORIES} from '../../lib/playerTrade'
const game=ref('全部'),keyword=ref(''),sort=ref('sales'),games=['全部',...ITEM_CATEGORIES],sorts=[{label:'推荐',value:'sales'},{label:'最新',value:'newest'},{label:'价格 ↑',value:'priceAsc'},{label:'价格 ↓',value:'priceDesc'}]
const {items,loading,error,total,load,more}=useList('/boost/listings',()=>({kind:'SERVICE',itemCategory:game.value,keyword:keyword.value,sort:sort.value}));function search(){if(/^(?:1[0-9]{4}|KK[0-9]{6,19})$/i.test(keyword.value.trim()))go('players/search',{userNo:keyword.value.trim()});else load()}onLoad(q=>{game.value=games.includes(q.itemCategory)?q.itemCategory:'全部';keyword.value=q.keyword||''});onShow(()=>load());onReachBottom(more)
</script>
<style scoped>.market-top{background:#fff;padding-bottom:4px}.categories{display:flex;overflow-x:auto;justify-content:flex-start;gap:18px;padding:20px 6px 6px}.categories button{flex-shrink:0;min-width:56px}.categories button{display:flex;flex-direction:column;align-items:center;gap:8px;font-size:12px}.categories .game-art,.all-icon{width:56px;height:56px;border-radius:15px}.all-icon{display:flex;align-items:center;justify-content:center;background:#f1f1f3}.chosen .all-icon{background:var(--yellow)}.chosen .game-art{outline:3px solid var(--yellow)}.chosen>text{font-weight:700}.market-top{padding-top:6px}.categories{padding:14px 4px 8px}.categories button{gap:5px;font-size:11px}.categories .chosen{color:#191919}.chosen{border-radius:14px;background:#fff9da}.market-top+.tabs{justify-content:space-between}.player-search-entry{display:block;text-align:right;width:100%;min-height:44px;font-size:12px;color:#666b78}</style>
